class VotingSystem:
    def __init__(self):
        self.candidates = {}
        self.votes = {}

    def create_candidate(self, name):
        """Create a new candidate"""
        self.candidates[name] = {"votes": 0, "results": {}}

    def add_candidate(self, name):
        """Add a new candidate to the system"""
        if name not in self.candidates:
            self.candidates[name] = {"votes": 0, "results": {}}
        else:
            print(f"Candidate {name} already exists.")

    def vote(self, candidate_name, voter_name):
        """Cast a vote for a candidate"""
        if candidate_name in self.candidates and voter_name in self.candidates[candidate_name]["results"]:
            self.candidates[candidate_name]["votes"] += 1
            self.candidates[candidate_name]["results"][voter_name] = self.candidates[candidate_name]["votes"]
        else:
            print("Invalid candidate or voter.")

    def view_results(self):
        """View the current results"""
        for candidate, votes in self.candidates.items():
            print(f"{candidate}: {votes['votes']} votes")
            for voter, vote_count in votes["results"].items():
                print(f"  - {voter}: {vote_count} votes")

